\title[Article Title]{The AI Roles Continuum: Blurring the Boundary Between Research and Engineering}












\author{\fnm{Deepak Babu} \sur{Piskala}} \email{prdeepak.babu@gmail.com} 











\abstract{The rapid scaling of deep neural networks and large language models has collapsed the once-clear divide between “research” and “engineering” in AI organizations. Drawing on public job descriptions, hiring loops, and org narratives from leading labs and tech companies, we propose the \textit{\textbf{AI Roles Continuum}}: a spectrum in which Research Scientists, Research Engineers, Applied Scientists and Machine Learning Engineers share overlapping mandates. Core competencies i.e distributed systems design, large-scale training and optimization, rigorous experimentation, and publication-minded inquiry are now broadly distributed across titles. Treating roles as fluid rather than siloed shortens research-to-production loops, improves iteration velocity, and strengthens organizational learning. We provide a taxonomy of competencies, map them to common titles, and discuss implications for hiring, ladders, and career development in modern AI enterprises.}

\keywords{AI organizations; research engineering; applied science; machine learning engineering; role taxonomy; socio-technical systems}





